import logging
import threading
import time
from ta_attenuator.config_parser import ConfigParser
from ta_attenuator.attenuators_pool import AttenuatorsPool
from ta_attenuator.fading_registry import FadingRegistry
from ta_attenuator.cells_pool import CellsPool
from ta_attenuator.fading_scenario import LinearFadingScenario, SingleCellLinearFadingScenario


class ta_attenuator(object):
    """Abstract Attenuator controlling library.

    Attenuator types that are currently supported:
        - JFW
        - RadioRack / Haojin
        - Hytem
        - TopYoung

    development project and code repository: https://wrgitlab.int.net.nokia.com/abstract_library/ta_attenuator

    developers mailing list: I_ABSTRACT_LIBRARY_DEV@internal.nsn.com

    Configuration examples are available in:
        - ta_attenuator/example/config/attenuators_config.yml

    Robot examples are available in:
        - ta_attenuator/example/set_attenuation.robot
        """
    # pylint: disable=too-many-instance-attributes, too-many-arguments, attribute-defined-outside-init
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def load_attenuation_config(self, ta_attenuator_config):
        """Load configuration from yaml file.
        :param ta_attenuator_config: path to yaml file with attenuator and cells configuration
        Example: example/config/attenuators_config.yml"""
        self.cells_pool = CellsPool()
        self.attenuators_pool = AttenuatorsPool()
        self.fading_registry = FadingRegistry()
        self.config_parser = ConfigParser(ta_attenuator_config, self.attenuators_pool, self.cells_pool)
        self.config_parser.load_attenuators()
        self.config_parser.load_cells()
        logging.info('Configuration loaded. Found attenuators: {}'.format(self.attenuators_pool.attenuators_registry))

    def require_attenuator_setup_of(self, cell_alias):
        """
        open connection to attenuator(s) controlling that cell and reserve pins of that cell
        :param cell_alias: cell_alias from the yaml configuration file, can be also a list of cells aliases
        """
        if isinstance(cell_alias, list):
            self._require_att_setup_as_list(cell_alias)
        else:
            self._require_att_setup_single_cell(cell_alias)

    def _require_att_setup_as_list(self, cell_names_list):
        for cell_alias in cell_names_list:
            self._require_att_setup_single_cell(cell_alias)

    def _require_att_setup_single_cell(self, cell_alias):
        cell = self.cells_pool.get_cell(cell_alias)
        self.cells_pool.append_used_names(cell_alias)
        logging.info('Cell found: {} on attenuator(s) {}'.format(cell_alias, cell.used_attenuator))
        cell.connect_to_attenuator(self.attenuators_pool)

    def set_attenuation(self, cell_alias, attenuation_value):
        """
        Set cell attenuation
        :param cell_alias: cell_alias from the yaml configuration file, can be also a list of cells aliases
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        """
        if isinstance(cell_alias, list):
            self._set_attenuation_multiple_cells(cell_alias, attenuation_value)
        else:
            self._set_attenuation_single_cell(cell_alias, attenuation_value)

    def read_attenuation(self, cell_alias):
        """
        Read cell attenuation
        :param cell_alias: cell_alias from the yaml configuration file
        :return attenuation value in db for the first rf_path of cell_alias
        :raises: :py:class:`ta_attenuator.UnknownCellAlias`: If cell with cell_alias was not required first
        """
        if cell_alias in self.cells_pool.used_names:
            cell = self.cells_pool.get_cell(cell_alias)
            return cell.read_attenuation(self.attenuators_pool)
        else:
            raise UnknownCellAlias("Cannot read Cell {}. "
                                   "Reading cell attenuation needs to be preceded with method 'require_attenuator_setup_of'".format(cell_alias))

    def _set_attenuation_single_cell(self, cell_alias, attenuation_value):
        if cell_alias in self.cells_pool.used_names:
            cell = self.cells_pool.get_cell(cell_alias)
            cell.set_attenuation(self.attenuators_pool, attenuation_value)
        else:
            raise UnknownCellAlias("Cannot set Cell {}. "
                                   "Setting cell attenuation needs to be preceded with method 'require_attenuator_setup_of'".format(cell_alias))

    def _set_attenuation_multiple_cells(self, cells_lst, attenuation_value):
        for cell_alias in cells_lst:
            self._set_attenuation_single_cell(cell_alias, attenuation_value)

    def set_attenuation_for_all_cells(self, attenuation_value):
        """
        Set attenuation on all cells that were already used in Require Attenuator Setup Of keyword
        :param attenuation_value: value to set in dB or %. It is string like '20dB' or '10%'
        :raises: :py:class:`ta_attenuator.UnknownCellAlias`: If cell with cell_alias was not required first
        """
        self._set_attenuation_multiple_cells(self.cells_pool.used_names, attenuation_value)

    def set_maximum_attenuation_for_all_cells_of_testline(self):
        """Set maximum attenuation for all cells declared in config file"""
        unused_cells = list()
        for cell in self.cells_pool.cells_registry.values():
            if cell.alias not in self.cells_pool.used_names:
                unused_cells.append(cell.alias)
        logging.info("Temporary setup of cells: {}".format(unused_cells))
        self.require_attenuator_setup_of(unused_cells)
        self.set_attenuation_for_all_cells("100%")
        logging.info("Releasing temporary cells: {}".format(unused_cells))
        self.release_attenuator_cell(unused_cells)

    def execute_fading_scenario(self, source_cell, target_cell, fading_step, fading_interval, fading_min, fading_max, confirm='True'):
        """
        Execute fading between source cell and target cell
        :param source_cell: source cell alias
        :param target_cell:  target cell alias
        :param fading_step: step in db
        :param fading_interval: interval in seconds, string like 0.5s or 1s
        :param fading_min: starting attenuation at source cell in db, example: 0db
        :param fading_max: ending attenuation at target cell in db, example 50db
        :param confirm: supported strings: true, yes, false, no; make sure that port / block has correct value after each write operation
        """
        source_cell = self.cells_pool.get_cell(source_cell)
        target_cell = self.cells_pool.get_cell(target_cell)
        source_cell_config_list = source_cell.cell_config_list
        target_cell_config_list = target_cell.cell_config_list
        source_rf_paths = self._extract_rf_paths(source_cell_config_list)
        target_rf_paths = self._extract_rf_paths(target_cell_config_list)
        if len(source_cell_config_list) > 1 or len(target_cell_config_list) > 1:
            raise FadingScenarioOnMultipleAttenuators('Fading Scenario on multiple attenuators is currently not supported.')
        att = self.attenuators_pool.get_attenuator(source_cell.used_attenuator[0])
        scenario_generator = LinearFadingScenario(attenuated_cell=source_rf_paths,
                                                  deattenuated_cell=target_rf_paths,
                                                  fading_step=fading_step,
                                                  fading_interval=fading_interval,
                                                  fading_min=att.convert_and_check_attenuation_value(fading_min),
                                                  fading_max=att.convert_and_check_attenuation_value(fading_max))
        att.execute_fading_scenario(scenario_generator, self._eval_confirm_parameter(str(confirm)))

    def _eval_confirm_parameter(self, confirm):
        if confirm.lower() in ['yes', 'true']:
            return True
        if confirm.lower() in ['no', 'false']:
            return False
        raise UnsupportedParameterValue('Unsupported confirm parameter value: {}, supported values: YES, TRUE, NO, FALSE'.format(confirm))

    def execute_single_cell_fading_scenario(self, cell_alias, fading_step, fading_interval, fading_min, fading_max, confirm='True'):
        """
        Execute fading of a single cell
        :param cell_alias: cell alias
        :param fading_step: step in db
        :param fading_interval: interval in seconds, string like 0.5s or 1s
        :param fading_min: starting attenuation at cell in db, example: 0db
        :param fading_max: ending attenuation at cell in db, example 50db
        :param confirm: supported strings: true, yes, false, no; make sure that port / block has correct value after each write operation
        """
        cell = self.cells_pool.get_cell(cell_alias)
        cell_config_list = cell.cell_config_list
        rf_paths = self._extract_rf_paths(cell_config_list)
        if len(cell_config_list) > 1:
            raise FadingScenarioOnMultipleAttenuators('Fading Scenario on multiple attenuators is currently not supported.')
        att = self.attenuators_pool.get_attenuator(cell.used_attenuator[0])
        scenario_generator = SingleCellLinearFadingScenario(faded_cell=rf_paths,
                                                            fading_step=fading_step,
                                                            fading_interval=fading_interval,
                                                            fading_min=att.convert_and_check_attenuation_value(fading_min),
                                                            fading_max=att.convert_and_check_attenuation_value(fading_max))
        att.execute_fading_scenario(scenario_generator, self._eval_confirm_parameter(str(confirm)))

    def _extract_rf_paths(self, cell_config_list):
        rf_paths = cell_config_list[0]['rf_paths_at_attenuator']
        return rf_paths

    def start_fading_scenario(self, fading_alias, source_cell, target_cell, fading_step, fading_interval, fading_min, fading_max, confirm='True'):
        """
        Execute fading between source cell and target cell in background
        :param fading_alias: Fading alias
        :param source_cell: source cell alias
        :param target_cell:  target cell alias
        :param fading_step: step in db
        :param fading_interval: interval in seconds, string like 0.5s or 1s
        :param fading_min: starting attenuation at source cell in db, example: 0db
        :param fading_max: ending attenuation at target cell in db, example 50db
        :param confirm: supported strings: true, yes, false, no; make sure that port / block has correct value after each write operation
        """
        fading_in_backgroud = FadingScenarioInBackground(
            self.execute_fading_scenario, source_cell, target_cell, fading_step, fading_interval, fading_min, fading_max,
            self._eval_confirm_parameter(str(confirm)))
        self.fading_registry.register_fading(fading_alias, fading_in_backgroud)
        fading_in_backgroud.start()

    def await_finish_of_fading_scenario(self, fading_alias):
        """
        Waits until ongoing fading is finished. Can be used only after Start Fading Scenario keyword
        :param fading_alias:     Alias of fading that should be awaited
        """
        fading_in_background = self.fading_registry.get_fading(fading_alias)
        while fading_in_background.isAlive():
            logging.info('Fading in background is still running')
            time.sleep(1)

    def release_attenuator_cell(self, cell_alias):
        """
        release cells connection to attenuator(s)
        :param cell_alias: cell_alias from the yml configuration file, can be also a list of cells aliases
         """
        if isinstance(cell_alias, list):
            self._disconnect_attenuator_multiple_cells(cell_alias)
        else:
            self._disconnect_attenuator_single_cell(cell_alias)

    def _disconnect_attenuator_single_cell(self, cell_alias):
        logging.info('Releasing cell attenuation: {}'.format(cell_alias))
        cell = self.cells_pool.get_cell(cell_alias)
        cell.disconnect_from_attenuator(self.attenuators_pool)
        self.cells_pool.release_used_names(cell_alias)

    def _disconnect_attenuator_multiple_cells(self, cells_list):
        for cell_alias in cells_list:
            self._disconnect_attenuator_single_cell(cell_alias)


class UnknownCellAlias(Exception):
    """Exception raised when cell alias does not exist in configuration file"""
    pass


class FadingScenarioOnMultipleAttenuators(Exception):
    """Exception: fading scenario on multiple attenuators is not yet supported"""
    pass


class UnsupportedParameterValue(Exception):
    """Exception raised when parameter value is not supported"""
    pass


class FadingScenarioInBackground(threading.Thread):
    """Class triggering fading scenario in background"""

    # pylint: disable=too-many-instance-attributes, too-many-arguments

    def __init__(self, execute_scenario, source_rf_paths, target_rf_paths, fading_step, fading_interval, fading_min, fading_max, confirm):
        threading.Thread.__init__(self)
        self.execute_scenario = execute_scenario
        self.source_rf_paths = source_rf_paths
        self.target_rf_paths = target_rf_paths
        self.fading_step = fading_step
        self.fading_interval = fading_interval
        self.fading_min = fading_min
        self.fading_max = fading_max
        self.confirm = confirm

    def run(self):
        """Starts fading scenario in background"""
        self.execute_scenario(self.source_rf_paths, self.target_rf_paths, self.fading_step, self.fading_interval, self.fading_min, self.fading_max,
                              self.confirm)
